// Verbatim community_release.rs:L755-L1175
fn normalized_package_name(name: &str) -> String {
    name.to_lowercase()
}

fn is_safe_package_relative_path(name: &str) -> bool {
    !name.is_empty()
        && name.trim() == name
        && !name.starts_with('/')
        && !name.contains('\\')
        && !name.contains(':')
        && name
            .split('/')
            .all(|component| !component.is_empty() && !matches!(component, "." | ".."))
}

